import {$,contrast,download} from './core.js';
$('#app').innerHTML=`<div class="toolbar"><label>Text colour<input type="color" id="fg" value="#263b30"></label><label>Background colour<input type="color" id="bg" value="#e5efcf"></label><button class="secondary" id="swap">Swap colours ⇄</button><button id="export">Export CSS ↓</button></div><div class="grid two"><div class="preview" id="preview"><span class="eyebrow" style="color:inherit">A LIVE PREVIEW</span><h2>Good design<br>includes everyone.</h2><p>This is normal body text. Readable colour choices help more people enjoy the experience.</p><span class="sample-btn"></span></div><div class="panel"><span class="eyebrow">Contrast ratio</span><div id="ratio" class="metric"></div><div id="checks" class="stack"></div><p class="small" id="hex"></p></div></div><div class="panel" style="margin-top:20px"><h2>Try a starting palette</h2><div class="toolbar"><button data-colors="#263b30,#e5efcf" class="secondary">Forest / lime</button><button data-colors="#ffffff,#202a25" class="secondary">Ivory / ink</button><button data-colors="#854d3a,#f6e9df" class="secondary">Clay / cream</button><button data-colors="#999999,#ffffff" class="secondary">Low-contrast example</button></div><p class="small">AA normal text requires 4.5:1; AA large text and UI components require 3:1; AAA normal text requires 7:1. Large text means at least 18 pt, or 14 pt bold. This tool checks contrast, not typography, focus behaviour or the full accessibility of a page.</p></div>`;
function render(){const a=$('#fg').value,b=$('#bg').value,r=contrast(a,b);$('#preview').style.color=a;$('#preview').style.background=b;$('#ratio').textContent=r.toFixed(2)+':1';$('#hex').textContent=`Text ${a.toUpperCase()} · Background ${b.toUpperCase()}`;$('#checks').innerHTML=[['AA · Normal text',4.5],['AA · Large text / UI',3],['AAA · Normal text',7]].map(([name,t])=>`<div class="row"><span>${name}</span><strong class="${r>=t?'pass':'fail'}">${r>=t?'Pass ✓':'Fail ×'}</strong></div>`).join('')}
$('#fg').oninput=render;$('#bg').oninput=render;$('#swap').onclick=()=>{const a=$('#fg').value;$('#fg').value=$('#bg').value;$('#bg').value=a;render()};document.querySelectorAll('[data-colors]').forEach(b=>b.onclick=()=>{const [a,c]=b.dataset.colors.split(',');$('#fg').value=a;$('#bg').value=c;render()});$('#export').onclick=()=>download('palette.css',`:root {\n  --text: ${$('#fg').value};\n  --background: ${$('#bg').value};\n}\n/* Contrast ratio: ${contrast($('#fg').value,$('#bg').value).toFixed(2)}:1 */`,'text/css');render();
